-- Sendro Instagram/SaaS foundation: Step 3 — empty channel account registry.
-- MANUAL EXECUTION ONLY: dev staging and main production share this DB.
-- Prerequisites: sendro_tenants exists; tenant 1 sunset-oia with 13 memberships.
-- Never executed by startup, CI, or a Render deploy.
-- This creates an EMPTY new table. It does not enroll an Instagram account,
-- enable any webhooks, modify WhatsApp records, or store any credentials.

BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '30s';

CREATE TABLE public.sendro_channel_accounts (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    tenant_id BIGINT NOT NULL
        REFERENCES public.sendro_tenants(id) ON DELETE RESTRICT,
    platform VARCHAR(20) NOT NULL,
    external_account_id VARCHAR(128) NOT NULL,
    display_name VARCHAR(160),
    status VARCHAR(16) NOT NULL DEFAULT 'pending',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT ck_sendro_channel_accounts_platform
        CHECK (platform IN ('instagram', 'whatsapp', 'messenger', 'tiktok')),
    CONSTRAINT ck_sendro_channel_accounts_status
        CHECK (status IN ('pending', 'testing', 'active', 'disabled')),
    CONSTRAINT uq_sendro_channel_accounts_platform_external
        UNIQUE (platform, external_account_id),
    CONSTRAINT uq_sendro_channel_accounts_id_tenant
        UNIQUE (id, tenant_id)
);

CREATE INDEX idx_sendro_channel_accounts_tenant_platform
    ON public.sendro_channel_accounts (tenant_id, platform);

COMMIT;

-- Verify 8 columns, zero rows, unique ownership per external account.
-- Do not insert token values into this table (or anywhere in repo/chat).
